{
  "v": 1,
  "language": "uk",
  "kind": "phrase",
  "pos": "phrase",
  "headword": {
    "ru": "до́брий день",
    "plain": "добрий день"
  },
  "overview": {
    "gloss": "hello, good day",
    "facts": [
      {
        "label": "Register",
        "value": "neutral, polite — usable with ти and Ви"
      },
      {
        "label": "Frequency",
        "value": "very common, core A1 greeting"
      }
    ],
    "notes": [
      "Used from the morning until about the evening; «до́брий ра́нок» and «до́брий ве́чір» cover the other parts of the day."
    ]
  },
  "sections": [
    {
      "id": "phrase-structure",
      "title": {
        "en": "Word by word",
        "ru": "Розбір за словами"
      },
      "layout": "list",
      "rows": [
        {
          "ru": "до́брий",
          "plain": "добрий",
          "gloss": "good (nom. sg. masc.)",
          "note": "agrees with «день»"
        },
        {
          "ru": "день",
          "plain": "день",
          "gloss": "day (nom. sg.)",
          "note": "the greeting is a nominative phrase, not a vocative"
        }
      ]
    },
    {
      "id": "phrase-usage",
      "title": {
        "en": "Usage & register",
        "ru": "Вживання і стиль"
      },
      "layout": "list",
      "rows": [
        {
          "ru": "до́брий день!",
          "plain": "добрий день!",
          "gloss": "a daytime greeting",
          "note": "say it entering a shop, a room, a call",
          "example": {
            "ru": "До́брий день! Чим я можу вам допомогти́?",
            "en": "Hello! How can I help you?"
          }
        },
        {
          "ru": "До́брий день, па́не Тара́се",
          "plain": "Добрий день, пане Тарасе",
          "gloss": "greeting with a vocative name",
          "note": "the name takes the vocative: Тара́с → Тара́се",
          "example": {
            "ru": "До́брий день, па́ні Окса́но!",
            "en": "Hello, Mrs Oksana!"
          }
        }
      ]
    },
    {
      "id": "phrase-variants",
      "title": {
        "en": "Variants & synonyms",
        "ru": "Варіанти і синоніми"
      },
      "layout": "list",
      "rows": [
        {
          "ru": "до́брого дня",
          "plain": "доброго дня",
          "gloss": "good day (genitive greeting)",
          "note": "also used when parting or as a wish"
        },
        {
          "ru": "приві́т",
          "plain": "привіт",
          "gloss": "hi (informal)",
          "note": "with friends, with ти"
        },
        {
          "ru": "віта́ю",
          "plain": "вітаю",
          "gloss": "I greet you (formal, warm)",
          "note": "warmer, a bit festive"
        }
      ]
    }
  ]
}
